// Tiny HTML parser: text -> tokens -> tree, with li auto-closing (error recovery)
const html = '<ul><li>One<li>Two</ul>';

// Step 1: tokenizer turns characters into start tags, end tags and text
function tokenize(s) {
  const tokens = [];
  const re = /<(\/?)([a-z0-9]+)>|([^<]+)/g;
  let m;
  while ((m = re.exec(s))) {
    if (m[2]) tokens.push({ type: m[1] ? 'end' : 'start', name: m[2] });
    else tokens.push({ type: 'text', text: m[3] });
  }
  return tokens;
}

// Step 2: tree builder keeps a stack of open elements
function build(tokens) {
  const root = { name: '#root', kids: [] };
  const stack = [root];
  for (const t of tokens) {
    const top = stack[stack.length - 1];
    if (t.type === 'text') top.kids.push(t.text);
    else if (t.type === 'start') {
      // Recovery rule: a new <li> closes an open <li>
      if (t.name === 'li' && top.name === 'li') stack.pop();
      const el = { name: t.name, kids: [] };
      stack[stack.length - 1].kids.push(el);
      stack.push(el);
    } else {
      while (stack.length > 1 && stack[stack.length - 1].name !== t.name) stack.pop();
      if (stack.length > 1) stack.pop();
    }
  }
  return root;
}

function show(node, depth) {
  for (const k of node.kids) {
    if (typeof k === 'string') console.log('  '.repeat(depth) + '"' + k + '"');
    else { console.log('  '.repeat(depth) + '<' + k.name + '>'); show(k, depth + 1); }
  }
}

console.log('Source:', html);
console.log('Tokens:', tokenize(html).map(t => t.name || t.text).join(' | '));
console.log('DOM tree:');
show(build(tokenize(html)), 0);

