// Which form controls end up in the submitted data?
const controls = [
  { name: 'agree', type: 'checkbox', checked: false, value: 'on' },
  { name: 'news', type: 'checkbox', checked: true, value: 'yes' },
  { type: 'checkbox', checked: true, value: 'x' },              // no name
  { name: 'beta', type: 'checkbox', checked: true, disabled: true, value: 'on' },
  { name: 'user', type: 'text', value: 'asha' },
  { name: 'tag', type: 'checkbox', checked: true, value: 'a' },
  { name: 'tag', type: 'checkbox', checked: true, value: 'b' }  // same name twice
];

// Rules from the HTML spec: skip no name, disabled, unchecked checkbox
function entries(list) {
  const out = [];
  for (const c of list) {
    if (!c.name || c.disabled) continue;
    if (c.type === 'checkbox' && !c.checked) continue;
    out.push([c.name, c.value]);
  }
  return out;
}

const sent = entries(controls);
console.log('Submitted pairs:', JSON.stringify(sent));
console.log('Query string:', sent.map(p => p[0] + '=' + p[1]).join('&'));

// Server side: a missing key means false, repeated keys form a list
const body = {};
for (const [k, v] of sent) (body[k] = body[k] || []).push(v);
console.log('agree is', body.agree ? 'true' : 'false (missing)');
console.log('tag list:', body.tag);

// One shared rule set used on the client and (again) on the server
const rules = {
  name: v => (typeof v === 'string' && v.trim().length >= 2) || 'name needs 2+ characters',
  age: v => (Number.isInteger(v) && v >= 18 && v <= 120) || 'age must be 18 to 120',
  email: v => (typeof v === 'string' && /^[^@\s]+@[^@\s]+\.[a-z]+$/i.test(v)) || 'email looks invalid'
};

function validate(data) {
  const errors = {};
  for (const field in rules) {
    const r = rules[field](data[field]);
    if (r !== true) errors[field] = r;
  }
  return errors;
}

// Client: runs in the form handler for instant feedback
const typed = { name: 'A', age: 17, email: 'a@b.co' };
console.log('Client check:', JSON.stringify(validate(typed)));

// Attacker skips the client and sends the request directly (like curl)
const forged = { name: 'Bob', age: -5, email: 'not-an-email' };
function serverHandler(body) {
  const errors = validate(body);              // never trust the client
  return Object.keys(errors).length
    ? { status: 422, errors }
    : { status: 201 };
}
console.log('Server on forged data:', JSON.stringify(serverHandler(forged)));
console.log('Server on good data:', JSON.stringify(serverHandler({ name: 'Bob', age: 30, email: 'b@x.io' })));

// Place table cells into a grid the way the browser does
const rows = [
  [{ t: 'A', rs: 2 }, { t: 'B' }, { t: 'C' }],
  [{ t: 'D' }, { t: 'E' }],          // correct: A already covers slot 0
  [{ t: 'F' }, { t: 'G' }, { t: 'H' }]
];
const wrong = [
  [{ t: 'A', rs: 2 }, { t: 'B' }],
  [{ t: 'X' }, { t: 'D' }]           // bug: 2 cells + covered slot = 3 wide
];

function layout(rows) {
  const grid = [];
  rows.forEach((cells, r) => {
    grid[r] = grid[r] || [];
    let c = 0;
    for (const cell of cells) {
      while (grid[r][c] !== undefined) c++;      // skip slots taken by a rowspan
      const cs = cell.cs || 1, rs = cell.rs || 1;
      for (let i = 0; i < rs; i++) {
        grid[r + i] = grid[r + i] || [];
        for (let j = 0; j < cs; j++) grid[r + i][c + j] = cell.t;
      }
      c += cs;
    }
  });
  return grid;
}

for (const [name, data] of [['good', rows], ['wrong', wrong]]) {
  const g = layout(data);
  console.log(name + ':');
  g.forEach(r => console.log('  ' + Array.from(r, x => x || '.').join(' ')));
  console.log('  widths:', g.map(r => r.length).join(','));
}
